export interface Property {
  id: string
  title: string
  price: string
  priceValue: number
  location: string
  area: string
  type: 'buy' | 'rent' | 'project'
  subtype?: 'new' | 'resell'
  category: 'Apartment' | 'Villa' | 'Plot' | 'Commercial' | 'Penthouse'
  bedrooms: number
  bathrooms: number
  status: 'Ready to Move' | 'Under Construction' | 'New Launch'
  badge?: string
  featured?: boolean
  gradientFrom: string
  gradientTo: string
  amenities: string[]
  description: string
  developer?: string
  possession?: string
  ownerName?: string
  ownerSince?: string
  ageOfProperty?: string
  mainImage?: string
  gallery?: string[]
  highlights: { label: string; value: string }[]
  floorPlans?: { name: string; area: string }[]
  slug: string
}

